import express from 'express';
import bcrypt from 'bcryptjs';
import { z } from 'zod';

const pengguna = [];
const Daftar = z.object({ email: z.email().toLowerCase(), password: z.string().min(8) });
const app = express();
app.use(express.json());
app.post('/auth/daftar', async (req, res) => {
  const h = Daftar.safeParse(req.body);
  if (!h.success) return res.status(400).json({ error: h.error.issues.map((i) => i.path.join('.')) });
  const { email, password } = h.data;
  if (pengguna.some((p) => p.email === email)) return res.status(409).json({ error: 'Email sudah terdaftar' });
  const baru = { id: pengguna.length + 1, email, hashPassword: await bcrypt.hash(password, 10), peran: 'pelanggan' };
  pengguna.push(baru);
  res.status(201).json({ id: baru.id, email: baru.email, peran: baru.peran });
});
const server = app.listen(3000);

const daftar = async (body) => {
  const r = await fetch('http://localhost:3000/auth/daftar', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  console.log(r.status, await r.json());
};
await daftar({ email: 'Sari@Toko.id', password: 'kopiSusu123', peran: 'admin' });
await daftar({ email: 'sari@toko.id', password: 'lainLagi123' });
await daftar({ email: 'bukan-email', password: '123' });
console.log(pengguna[0].hashPassword.startsWith('$2b$'), pengguna.length);
server.close();

